const mktData = $input.first().json;
const results = mktData.results || [];

const nifty = results.find(r => r.name === 'NIFTY 50') || {};
const bankNifty = results.find(r => r.name === 'BANK NIFTY') || {};
const sensex = results.find(r => r.name === 'SENSEX') || {};

const fmt = (p) => p ? Number(p).toLocaleString('en-IN', {maximumFractionDigits: 2}) : 'N/A';
const fmtChg = (c) => c !== undefined ? (c >= 0 ? '+' : '') + Number(c).toFixed(2) + '%' : 'N/A';

const niftyPrice = fmt(nifty.price);
const niftyChange = fmtChg(nifty.change);
const bankNiftyPrice = fmt(bankNifty.price);
const bankNiftyChange = fmtChg(bankNifty.change);
const sensexPrice = fmt(sensex.price);
const marketStatus = mktData.status || 'CLOSED';

// Unique daily seed — prevents duplicate topics week over week
const now = new Date();
const startOfYear = new Date(now.getFullYear(), 0, 1);
const weekNum = Math.floor((now - startOfYear) / (7 * 24 * 60 * 60 * 1000));
const day = now.getDay();
const uniqueSeed = weekNum * 10 + day;

const sectors = ['Banking & Finance', 'IT Services', 'Auto & EV', 'Energy & Oil', 'FMCG & Consumer', 'Pharma & Healthcare', 'Realty & Infrastructure', 'Metals & Mining', 'Telecom', 'Defence & Aerospace'];
const featuredStocks = ['HDFCBANK', 'ICICIBANK', 'TCS', 'INFY', 'RELIANCE', 'NTPC', 'HEROMOTOCO', 'TATAMOTORS', 'SUNPHARMA', 'MARUTI', 'WIPRO', 'ADANIPORTS', 'LT', 'BAJFINANCE', 'ZOMATO'];

const sector = sectors[uniqueSeed % sectors.length];
const stock = featuredStocks[uniqueSeed % featuredStocks.length];

const marketSummary = `Market Snapshot (${marketStatus}):
NIFTY 50: ${niftyPrice} (${niftyChange})
BANK NIFTY: ${bankNiftyPrice} (${bankNiftyChange})
SENSEX: ${sensexPrice}`;

const cta = `Want data-backed market insights? Visit marketbeaconpro.com and use code ALPHA7 for 7 days free access. Track 40+ stocks across multiple sectors with 10+ strategies in one dashboard.`;
const hashtags = '#MarketBeacon #StockMarketIndia #NSE #BSE #Nifty50 #Trading #InvestmentResearch #SwingTrading #IndianStocks #MarketAnalysis';
const disclaimer = 'Disclaimer: This is for educational and informational purposes only. Not investment advice. Not a recommendation to buy, sell, or hold any security. Please consult a SEBI-registered investment advisor before making any investment decisions.';

const style = `STYLE: 200-250 words. Short paragraphs. Use emojis naturally. Start with a strong hook. Mention smart money and operators. Sound human, not corporate. Plain text only. No asterisks. No markdown formatting.`;

let prompt;

if (day === 1) {
  prompt = `${style}

Write a LinkedIn post titled: "Weekly Market Outlook: NIFTY and Sector Rotation Analysis"

USE THESE EXACT PRICES (do not change them):
${marketSummary}

Cover:
1. NIFTY at ${niftyPrice} - what this level means structurally
2. BANK NIFTY at ${bankNiftyPrice} - momentum check
3. ${sector} sector smart money signals
4. Key levels to watch this week

End with:
${cta}
${disclaimer}

Hashtags: #WeeklyOutlook #NiftyAnalysis #BankNifty ${hashtags}`;
} else if (day === 2) {
  prompt = `${style}

Write a LinkedIn post titled: "Sector Spotlight: ${sector}"

Market context:
${marketSummary}

Cover:
1. Why ${sector} is catching smart money attention this week
2. Top stocks showing institutional accumulation patterns
3. Key metrics making this sector interesting
4. Price action levels to watch

End with:
${cta}
${disclaimer}

Hashtags: #SectorSpotlight #${sector.replace(/[^a-zA-Z0-9]/g,'')} #SectorRotation ${hashtags}`;
} else if (day === 3) {
  prompt = `${style}

Write a LinkedIn post titled: "Stock in Focus: ${stock}"

Market context:
${marketSummary}

Cover:
1. Why ${stock} is on radar with NIFTY at ${niftyPrice}
2. Fundamental check - ROCE, Debt-to-Equity, promoter holding
3. FII and DII smart money signals
4. Technical setup - breakout, retest, or consolidation

End with:
${cta}
${disclaimer}

Hashtags: #${stock} #StockInFocus #StockAnalysis ${hashtags}`;
} else if (day === 4) {
  prompt = `${style}

Write a LinkedIn post titled: "How MarketBeacon Institutional Audit Score Works"

Market context:
${marketSummary}

Cover:
1. The problem: too many stocks to track manually every morning
2. What the Institutional Audit Score measures - quality plus strategy alignment
3. How 10+ strategies run simultaneously to find multi-aligned stocks
4. Data over emotions - a practical example from today's market

End with:
${cta}
${disclaimer}

Hashtags: #TradingEducation #StockMarket #AuditScore #InvestSmart ${hashtags}`;
} else if (day === 5) {
  prompt = `${style}

Write a LinkedIn post titled: "Weekly Market Wrap: Key Takeaways for Traders"

This week closing data:
${marketSummary}

Cover:
1. NIFTY closed at ${niftyPrice} - was it a bullish or bearish week
2. BANK NIFTY at ${bankNiftyPrice} - what the price action signals
3. Best and worst sectors - where did smart money flow
4. ${stock} weekly operator signals
5. What to watch for next week

End with:
${cta}
${disclaimer}

Hashtags: #WeeklyWrap #MarketRecap #NiftyWrap ${hashtags}`;
} else if (day === 6) {
  prompt = `${style}

Write a LinkedIn post titled: "Behind MarketBeacon: Building a Better Stock Dashboard"

Markets are closed today. ${marketSummary}

Cover:
1. The problem: checking 20+ stocks manually every morning
2. The solution: one dashboard for 40+ stocks, 10+ strategies, live indices
3. Features: institutional audit scoring, sector rotation signals, real-time NIFTY tracking
4. Built by traders for traders - 15 minutes a day, data-backed decisions

End with:
${cta}
${disclaimer}

Hashtags: #MarketBeacon #BuiltByTraders #TradingTools #Fintech ${hashtags}`;
} else {
  prompt = `${style}

Write a LinkedIn post titled: "Weekend Reflection: Lessons from Smart Money"

This week in markets:
${marketSummary}

Cover:
1. NIFTY at ${niftyPrice} - what this tells smart traders looking ahead
2. Data beats emotions - key lesson from this week
3. Questions every swing trader should ask before Monday
4. What MarketBeacon has on its radar for next week

End with:
${cta}
${disclaimer}

Hashtags: #WeekendReflection #TradingPsychology #MindsetMatters ${hashtags}`;
}

return [{ json: { dayPrompt: prompt, sector, stock, niftyPrice, bankNiftyPrice, marketStatus, day, uniqueSeed } }];

const input = $input.first().json;
const commentary = input.choices?.[0]?.message?.content || '';
const author = 'urn:li:person:HfsN9dKuZE';
return [{ json: { author, commentary, visibility: 'PUBLIC', distribution: { feedDistribution: 'MAIN_FEED', targetEntities: [], thirdPartyDistributionChannels: [] }, lifecycleState: 'PUBLISHED' } }];
